from pathlib import Path
import pandas as pd
R=Path(__file__).resolve().parents[1]; P=R/'data/processed'; out=R/'reports/POPULATION_ROBUSTNESS_MATRIX.html'; d=pd.read_csv(P/'population_robustness_matrix.csv'); d=d.rename(columns={'scope':'Population / evaluation','participants':'Participants','healthy':'Healthy','stroke':'Stroke','auroc':'AUROC','brier':'Brier score','balanced_accuracy':'Balanced accuracy'}); html=d.to_html(index=False,float_format=lambda x:f'{x:.3f}',classes='metrics'); out.write_text(f'''<!doctype html><html><head><meta charset="utf-8"><title>Population Robustness Matrix</title><style>body{{font-family:Segoe UI,Arial;background:#f5f7fa;color:#172b4d;margin:48px}}h1{{color:#102a43}}.lead{{font-size:18px;max-width:900px}}table{{border-collapse:collapse;background:white;box-shadow:0 4px 18px #ccd6e0;margin-top:28px}}th,td{{padding:14px 18px;border-bottom:1px solid #dfe5eb;text-align:right}}th:first-child,td:first-child{{text-align:left}}th{{background:#173f5f;color:white}}tr:last-child{{background:#fff3cd;font-weight:700}}.note{{margin-top:24px;background:#e8f1f8;border-left:5px solid #1976a3;padding:16px;max-width:900px}}</style></head><body><h1>Population Robustness Matrix</h1><p class="lead">Expanded Felius + Voisard + Sint Inception model. Internal values are participant-level out-of-fold estimates; RevalExo is the untouched external benchmark.</p>{html}<div class="note"><b>Interpretation:</b> RevalExo remains the most important generalisation result. The source-specific rows are not independent external validation, and the small RevalExo cohort limits clinical conclusions.</div></body></html>''',encoding='utf-8'); print(out)
